import { createClientFromRequest } from 'npm:@base44/sdk@0.8.48';
import { requireConfiguredEmailTransport, sendWithConfiguredEmailTransport } from './emailRouter.ts';

const RUNTIME_VERSION='kotc-email-branding-2026-10-06-r15';
const KOTC_BASIC_HEADER_TITLE='KING OF THE COURT';
const KOTC_BASIC_HEADER_SUBTITLE='Your Personal Results';
const APP_BASE_URL='https://rallyhub.ie';
const DEFAULT_TABS=['live','players','rounds','leaderboard','event_info'];
function shareConfig(share:any){let tabs=DEFAULT_TABS;try{const parsed=share?.visible_tabs_json?JSON.parse(share.visible_tabs_json):null;if(Array.isArray(parsed)&&parsed.length)tabs=parsed.filter((v:any)=>['live','players','rounds','scores','leaderboard','event_info'].includes(String(v)));}catch{}return{tabs:[...new Set(tabs)],scoring_access:['off','read_only','verified_players','open_players'].includes(share?.scoring_access)?share.scoring_access:'read_only',identification_mode:share?.identification_mode==='none'?'none':'host_code'};}
function broadcastVisible(row:any,session:any){if(!row||row.status!=='published')return false;const mode=row.expiry_mode||'manual';if(mode==='event_start'&&['in_progress','paused','completed','finalised','abandoned'].includes(session.status))return false;if(row.expires_at&&Date.parse(row.expires_at)<=Date.now())return false;return true;}
const SHARED_GMAIL_ADDRESS='clarepb2025@gmail.com';
function token(){const b=new Uint8Array(32);crypto.getRandomValues(b);return Array.from(b).map(x=>x.toString(16).padStart(2,'0')).join('');}
function nowIso(){return new Date().toISOString();}
function firstName(value:any){const raw=String(value||'Player').trim();if(raw.startsWith('[')&&raw.endsWith(']'))return raw;const clean=raw.replace(/,/g,' ').trim();return clean.split(/\s+/)[0]||'Player';}
function hostName(user:any){return String(user?.full_name||user?.name||String(user?.email||'').split('@')[0]||'Session Host').trim();}
const PLAYER_LINK_LABEL='Open your private KOTC player summary';
const RESULTS_LINK_LABEL='Open the shared KOTC results';
const GUIDE_LINK_LABEL='Clare Pickleball Player Link Infographic';
const CLARE_GUIDE_PAGE=`${APP_BASE_URL}/guides/clare-pickleball/player-link`;
function emailTemplate(session:any,recipientName:string,host:string,clubName:string,competitionFormat:string,playerLink:string,resultsLink:string,guideAssetUrl:string){const guidePageUrl=guideAssetUrl?CLARE_GUIDE_PAGE:'';const guide=guidePageUrl?`\n\nWe’ve also put together a simple infographic showing how to use the player link:\n${GUIDE_LINK_LABEL}`:'';const resultsCopy=`Your private ${competitionFormat} player summary is ready. It shows your final rank, wins/losses, point differential and every round you played.\n\n${PLAYER_LINK_LABEL}\n\nThe shared event link remains available for the final podium and completed round results:\n${RESULTS_LINK_LABEL}${guide}`;const signature=/^clare pickleball$/i.test(String(clubName||'').trim())?'Yours in sport,\nBrian Moore\nChairperson\nClare Pickleball Club\nPhone / WhatsApp: +353 87 810 0333':`Regards,\n${host}\nSession Host\n${clubName}`;return {subject:`${session.name} — your KOTC result`,body:`Hi ${firstName(recipientName)},\n\nThanks for playing in ${session.name}.\n\n${resultsCopy}\n\nThanks for playing. Looking forward to seeing you on court again soon.\n\n${signature}`,guidePageUrl};}
function escapeHtml(value:string){return String(value||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function sanitiseEditorHtml(value:string){let html=String(value||'');html=html.replace(/<(script|style|iframe|object|embed|form|input|textarea|button|img)[^>]*>[\s\S]*?<\/\1>/gi,'').replace(/<(script|style|iframe|object|embed|form|input|textarea|button|img)[^>]*\/?>/gi,'');html=html.replace(/\son\w+\s*=\s*(['"]).*?\1/gi,'').replace(/\son\w+\s*=\s*[^\s>]+/gi,'');html=html.replace(/<(?!\/?(?:div|p|br|strong|b|em|i|u|h1|h2|h3|ul|ol|li|a|span|font)\b)[^>]+>/gi,'');html=html.replace(/href\s*=\s*(['"])(?!https?:\/\/|mailto:|tel:)[^'"]*\1/gi,'href="#"');return html;}
function emailCta(label:string,url:string,variant:string){
 const p:any=variant==='results'?{bg:'#079447',fg:'#ffffff',sub:'Final podium & completed rounds',icon:'&#127942;'}:variant==='guide'?{bg:'#fff2a8',fg:'#082b63',sub:'Simple visual guide',icon:'&#128196;'}:{bg:'#075db8',fg:'#ffffff',sub:'Your private results',icon:'&#128202;'};
 return `<table role="presentation" align="center" width="300" cellspacing="0" cellpadding="0" border="0" style="width:300px;max-width:100%;margin:14px auto 22px;border-collapse:separate"><tr><td bgcolor="${p.bg}" style="background:${p.bg};border-radius:9px;box-shadow:0 4px 10px rgba(15,23,42,.14)"><a href="${escapeHtml(url)}" target="_blank" style="display:block;padding:12px 16px;text-decoration:none;color:${p.fg};font-family:Arial,Helvetica,sans-serif;border-radius:9px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="border-collapse:collapse"><tr><td width="34" align="center" valign="middle" style="width:34px;font-size:20px;line-height:20px;color:${p.fg}">${p.icon}</td><td valign="middle" style="padding-left:9px;text-align:left;font-family:Arial,Helvetica,sans-serif"><div style="font-size:14px;line-height:17px;font-weight:700;color:${p.fg}">${escapeHtml(label)}</div><div style="margin-top:2px;font-size:10px;line-height:13px;font-weight:400;color:${p.fg}">${escapeHtml(p.sub)}</div></td></tr></table></a></td></tr></table>`;
}
function replaceActionLabel(html:string,label:string,url:string,variant:string){const cta=emailCta(label,url,variant);const escaped=escapeHtml(label);return html.includes(escaped)?html.replace(escaped,cta):html.replace(label,cta);}
function emailBodies(value:string,recipientName:string,playerLink:string,resultsLink:string,guidePageUrl:string,richHtml:string=''){const personalised=personaliseEditableBody(value,recipientName);let plain=personalised;let html=richHtml?sanitiseEditorHtml(personaliseEditableBody(richHtml,recipientName)):escapeHtml(personalised);if(playerLink){plain=plain.replace(PLAYER_LINK_LABEL,`${PLAYER_LINK_LABEL}: ${playerLink}`);html=replaceActionLabel(html,PLAYER_LINK_LABEL,playerLink,'player');}if(resultsLink){plain=plain.replace(RESULTS_LINK_LABEL,`${RESULTS_LINK_LABEL}: ${resultsLink}`);html=replaceActionLabel(html,RESULTS_LINK_LABEL,resultsLink,'results');}if(guidePageUrl){plain=plain.replace(GUIDE_LINK_LABEL,`${GUIDE_LINK_LABEL}: ${guidePageUrl}`);html=replaceActionLabel(html,GUIDE_LINK_LABEL,guidePageUrl,'guide');}if(!richHtml)html=html.replace(/\n/g,'<br>');html=`<div style="font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.55;color:#111827">${html}</div>`;return{textBody:plain,htmlBody:html};}
